package ru.truetv.launcher;
import android.content.*;
import android.content.pm.*;
import java.io.*;
import java.util.*;
import org.json.*;

/** Physical removal is available only on already-writable, non-enforcing firmware. */
public final class FactoryRemoval {
 private FactoryRemoval(){}
 private static void require(ShellReply r)throws IOException {if(r.code!=0)throw new IOException(r.text.isEmpty()?"Root-команда не выполнена":r.text);}
 private static File base(Context c){return new File(c.getFilesDir(),"factory-backups");}
 public static List<String> backups(Context c){ArrayList<String> result=new ArrayList<>();File[] files=base(c).listFiles();if(files!=null)for(File f:files)if(SystemCommands.validPackage(f.getName())&&new File(f,"manifest.json").isFile())result.add(f.getName());return result;}
 private static List<String> paths(Context c,ExpertBackend b,String pkg)throws Exception {
  Set<String> codes=PackagePolicy.codePaths(b.shell("dumpsys package "+pkg).text+"\n"+b.shell("pm path "+pkg).text);LinkedHashSet<String> result=new LinkedHashSet<>();
  for(String code:codes){String candidate=code.endsWith(".apk")?code:code+"/base.apk";if(!PackagePolicy.factoryPath(candidate))continue;String directory=code.endsWith(".apk")?new File(code).getParent():code;ShellReply listing=b.shell("find "+PackagePolicy.quote(directory)+" -maxdepth 2 -type f -name '*.apk'");require(listing);for(String path:listing.text.split("\\r?\\n")){if(path.isEmpty())continue;if(!PackagePolicy.factoryPath(path)||!path.startsWith(directory+"/"))throw new IOException("Неоднозначный каталог APK");PackageInfo archive=c.getPackageManager().getPackageArchiveInfo(path,0);if(archive==null||!pkg.equals(archive.packageName))throw new IOException("Каталог содержит другой пакет или неподтверждённый APK: "+path);result.add(path);}}
  if(result.isEmpty())throw new IOException("Заводской APK не найден однозначно; физическое удаление недоступно");return new ArrayList<>(result);
 }
 public static String remove(Context c,ExpertBackend b,String pkg)throws Exception {
  if(!b.hasRootShell())throw new IOException(Ui.word(c,"ADB подключён без root-прав. Для физического удаления выберите «Имеющийся root» в «Подключение» либо используйте ADB, уже работающий как root. Файлы не удалялись.","ADB has no root privileges. Select Existing root under Connection or use ADB already running as root. No files were deleted."));b.prepareOverride(pkg);String verified=b.shell("getprop ro.boot.verifiedbootstate").text,verity=b.shell("getprop ro.boot.veritymode").text;if(verified.trim().equals("green")||verity.trim().equals("enforcing"))throw new IOException("Прошивка проверяет системный раздел при загрузке. Физическое удаление в этом режиме недоступно; AVB автоматически не отключается.");
  List<String> paths=paths(c,b,pkg);for(String path:paths)require(b.shell("test -w "+PackagePolicy.quote(new File(path).getParent())));
  File folder=new File(base(c),pkg);if(new File(folder,"manifest.json").exists())throw new IOException("Уже есть резервная копия этого пакета. Сначала восстановите или удалите её.");if(!folder.exists()&&!folder.mkdirs())throw new IOException("Не удалось создать резервную копию");JSONArray records=new JSONArray();
  for(int i=0;i<paths.size();i++){String original=paths.get(i);File backup=new File(folder,i+".apk");require(b.shell("cp "+PackagePolicy.quote(original)+" "+PackagePolicy.quote(backup.getAbsolutePath())));require(b.shell("chmod 644 "+PackagePolicy.quote(backup.getAbsolutePath())));require(b.shell("cmp -s "+PackagePolicy.quote(original)+" "+PackagePolicy.quote(backup.getAbsolutePath())));JSONObject row=new JSONObject();row.put("source",original);row.put("backup",backup.getName());records.put(row);}
  JSONObject manifest=new JSONObject();manifest.put("package",pkg);manifest.put("files",records);try(FileOutputStream out=new FileOutputStream(new File(folder,"manifest.json"))){out.write(manifest.toString().getBytes("UTF-8"));out.getFD().sync();}
  b.removeEverywhere(pkg);try{for(String path:paths)require(b.shell(PackagePolicy.deleteApk(path)));for(String path:paths)require(b.shell("test ! -e "+PackagePolicy.quote(path)));}catch(Exception failure){try{restore(c,b,pkg);}catch(Exception rollback){failure.addSuppressed(rollback);}throw failure;}
  return "Заводские APK удалены из прошивки, установки всех профилей удалены. Перезагрузите ТВ для обновления системного списка. Резервная копия сохранена в лаунчере; её можно восстановить или отдельно удалить в меню «Подключение».";
 }
 public static void restore(Context c,ExpertBackend b,String pkg)throws Exception {if(!b.hasRootShell()||!SystemCommands.validPackage(pkg))throw new IOException("Нужен root и корректный пакет");File folder=new File(base(c),pkg);StringBuilder text=new StringBuilder();try(BufferedReader in=new BufferedReader(new InputStreamReader(new FileInputStream(new File(folder,"manifest.json")),"UTF-8"))){String line;while((line=in.readLine())!=null){text.append(line);if(text.length()>65536)throw new IOException("Неверный манифест");}}JSONObject manifest=new JSONObject(text.toString());if(!pkg.equals(manifest.getString("package")))throw new IOException("Не совпал пакет резервной копии");JSONArray entries=manifest.getJSONArray("files");for(int i=0;i<entries.length();i++){JSONObject row=entries.getJSONObject(i);String path=row.getString("source"),name=row.getString("backup");if(!PackagePolicy.factoryPath(path)||!name.matches("[0-9]+\\.apk"))throw new IOException("Недопустимый путь резервной копии");File backup=new File(folder,name);PackageInfo info=c.getPackageManager().getPackageArchiveInfo(backup.getAbsolutePath(),0);if(info==null||!pkg.equals(info.packageName))throw new IOException("Резервная копия не соответствует пакету");require(b.shell("cp "+PackagePolicy.quote(backup.getAbsolutePath())+" "+PackagePolicy.quote(path)));require(b.shell("chmod 644 "+PackagePolicy.quote(path)));require(b.shell("restorecon "+PackagePolicy.quote(path)));require(b.shell("cmp -s "+PackagePolicy.quote(backup.getAbsolutePath())+" "+PackagePolicy.quote(path)));}b.restoreEverywhere(pkg);}
 public static void discard(Context c,String pkg)throws IOException {if(!SystemCommands.validPackage(pkg))throw new IOException("Неверный пакет");FileCore.erase(new File(base(c),pkg),FileCore.NEVER);}
}
